import React, { useState, useEffect } from 'react';

const Opportunities = () => {
  const [opportunities, setOpportunities] = useState([]);
  const [filterWilaya, setFilterWilaya] = useState('');
  const [filterTech, setFilterTech] = useState('');

  const algeriaWilayas = ["Adrar", "Chlef", "Alger", "Constantine", "Oran", "Sétif"];
  const techs = ["React", "Java", "Python", "PHP", "Flutter"];

  // دالة وهمية لاستخدام setOpportunities مؤقتاً لتجنب التحذير
  useEffect(() => {
    // هنا سيتم جلب البيانات لاحقاً من Django
    setOpportunities([]); 
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 p-8 text-right" dir="rtl">
      <h1 className="text-3xl font-bold text-indigo-900 mb-8 text-center">استكشف فرص التربص</h1>

      <div className="bg-white p-6 rounded-xl shadow-sm mb-10 flex flex-wrap gap-4 items-end">
        <div className="flex-1 min-w-[200px]">
          <label className="block text-sm font-bold text-gray-700 mb-2">البحث حسب الولاية:</label>
          <select 
            value={filterWilaya} // ربط القيمة بالـ State
            className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
            onChange={(e) => setFilterWilaya(e.target.value)}
          >
            <option value="">كل الولايات</option>
            {algeriaWilayas.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>

        <div className="flex-1 min-w-[200px]">
          <label className="block text-sm font-bold text-gray-700 mb-2">حسب التقنية:</label>
          <select 
            value={filterTech} // ربط القيمة بالـ State
            className="w-full p-2 border rounded-lg outline-none focus:ring-2 focus:ring-indigo-500"
            onChange={(e) => setFilterTech(e.target.value)}
          >
            <option value="">كل التقنيات</option>
            {techs.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
      </div>

      {/* تنبيه بسيط في حال كانت القائمة فارغة */}
      {opportunities.length === 0 && (
        <p className="text-center text-gray-500">لا توجد فرص متاحة حالياً لفلتر: {filterWilaya || "كل الولايات"}</p>
      )}
    </div>
  );
};

export default Opportunities;
